  "guide/pillar-gap-ja": {
    "eyebrow": "日柱",
    "title": "甲子日柱",
    "summary": "Saju-Link 如何解读日柱甲子——日支所藏的天干相对于日干是什么——均按其计算规则原样列出。",
    "backLabel": "计算基础",
    "sections": [
      {
        "title": "甲子是六十甲子中的第1个日柱",
        "blocks": [
          {
            "p": "当出生日的干支为甲子时，日干是甲（阳木），日支是子（鼠）。在六十甲子中，它是第1个组合。"
          },
          {
            "p": "Saju-Link 把日干为甲的人称为“甲木（阳木）”，结果页面显示的一句话是：“笔直生长的大树。方向一旦定下就不再动摇，宁可硬撑也不愿弯折。” 这句话与下方的解读或分数无关。"
          }
        ]
      },
      {
        "title": "日支子所藏的天干相对于日干是什么",
        "blocks": [
          {
            "p": "日支是配偶位置。从日干甲来看，子所藏的天干如下。本气天干（癸）是这个地支的代表能量。"
          },
          {
            "table": {
              "caption": "甲子日支的藏干",
              "head": [
                "藏干",
                "位置",
                "占比",
                "相对于日干甲"
              ],
              "rows": [
                [
                  "壬水（阳水）",
                  "余气（餘氣）",
                  "{hidJaYeo}",
                  "偏印（偏印）"
                ],
                [
                  "癸水（阴水）",
                  "本气（本氣）",
                  "{hidJaBon}",
                  "正印（正印）"
                ]
              ]
            }
          }
        ]
      },
      {
        "title": "配偶位置与这个日柱",
        "blocks": [
          {
            "p": "传统命理将配偶位置解读为：男性为正财（正財），女性为正官（正官）。以甲为日干时，正财是己，正官是辛。"
          },
          {
            "p": "男性的配偶位置（正财）是己。己不藏在子之中。"
          },
          {
            "p": "女性的配偶位置（正官）是辛。辛不藏在子之中。"
          }
        ]
      },
      {
        "title": "相邻的日柱及其组成字符",
        "blocks": [
          {
            "p": "在六十甲子中，前一个日柱是[癸亥](/guide/pillar-gye-hae)，后一个是[乙丑](/guide/pillar-eul-chuk)。"
          },
          {
            "p": "它由[甲木（阳木）](/guide/stem-gap)和[子（鼠）](/guide/branch-ja)组成。"
          }
        ]
      },
      {
        "kind": "note",
        "title": "本指南不涉及的内容",
        "blocks": [
          {
            "ul": [
              "一个日柱并不能决定一个人或一段关系。八字是从四柱八个字符之间的关系来解读的。",
              "配偶位置的解读沿用了传统命理的规则，如果您不填写性别，则不解读这个位置。"
            ]
          }
        ]
      }
    ]
  },

